C=[]
bio='这位身高约两米半的四巧堂高手幼年因听觉与言语障碍被遗弃，由长老收养，练成极高武艺、唇读和独特手语。他没有接受识字教育，养父希望隔绝世间欺凌，这种保护同时限制了他的沟通。幼年一次来到后来属于陈长青的大宅，他接受了自己不能理解的安排，直到七十二岁生命终点才开始沿相反方向逐日生活；遇到卫斯理时，他处在回程中的四十七岁阶段。'+'他记得去程中看过空难报道，想阻止数百人死亡，却因无法说明而抢夺武器、挟持人质，大闹机场。白素用手语建立信任，他才说出经历。身体极强使他能掀翻钢桌、制住警员和总监，却无法解决制度与沟通的困局；最终大家误解新闻播放时间，仍未阻止空难，只救下本应乘机的大亨。午夜过后他已经离开众人的时段，具体消失过程无人看见。卡片保留救人之心与急切手段的矛盾，双程生命不是随意往返所有年代，更不是知道未来一切；他可以记错解释、需要翻译，也应在发现挟持伤害别人时学习别种表达。'
tr=[('知道亲历的灾祸可能重演','没有通行的沟通方式','急于阻止，可能采取过激手段；能沟通后应解释并释放无关者。'),('有人以四巧堂手语诚恳相待','确认对方理解自己','建立信任、详细回忆，不把对方当成必须服从的部属。'),('午夜将到而别人要留住自己','逆行生命不受主观选择控制','说明无法保证留下，珍惜现有时间而不承诺任意重逢。')]
c=make('shuangcheng_giant','四巧堂双程巨人',bio,'在陈宅沉睡期间越过午夜后不在原处，按其经历继续回到前一日；未实际看见消失方式。',[skill('巨力与四巧堂武艺','长期武术训练结合极强壮身体，可迅速摔开成年人、撞翻桌子并制住近身对手。','约两米半的巨体配合迅速动作，仍有真实接触与动作过程。',['近身制敌','自卫突破','手语及唇读沟通'],'不等于防弹、远程放能；手语需要对方理解，唇读须看清嘴部。'),skill('双程生命','去程到死亡节点后开始反向逐日生活，每日仍能与当日人们交往，午夜后进入此前一日。','同一时段可见可触；本次离开在众人离场时发生。',['保留亲历去程事件的记忆','尝试警告特定灾难'],'被动时间路径；不能自主选日、停留、带人穿越、创造分身或知道未亲历的一切；两程事件可不同。','被动特性')],'帮助面临危险的人，重温珍贵经历，并在陌生社会找到能够理解自己的人。',['不愿坐视已知惨剧','珍惜养育与真诚信任','以亲历记忆为依据而非假装全知'],tr,[ev(117,547,563,'体格和手语'),ev(117,1015,1037,'记忆和变化边界'),ev(117,1145,1184,'实际巨力'),ev(117,1403,1508,'养父、童年和沟通'),ev(117,1638,1675,'双程起点'),ev(117,2443,2497,'空难误判及消失')],(5,0,3,5,2,8),['掀钢桌、摔人等近身表现','未显示主动能量攻击','时间路径影响自身，未展示群体改写','巨体与武艺有持续性但仍睡眠','近身为主，记忆不等于远程攻击','高于卫白的具体武艺评价与现场制敌'],roles=['单书主角'],negative=(3,2,2),body={'destruction':'能摔飞警员、撞翻钢桌；不能由比较描写推成摧毁建筑。','durability':'强壮人体，缺乏免疫枪弹、窒息或毒物的证据。','speed':'近战动作使在场人来不及看清；没有精确速度或躲避已发射子弹的证据。','mind':'记忆良好，能唇读；沟通受限而非认知低下。'},terms=[{'term':'双程生命','explanation':'本书中的正向经历后反向逐日生活，不是把正常人生简单延长一倍。'}],mastery='被动触发',uncertain=['转变的具体装置与地下通道未被找到。','回程如何与客观时间相交，只给出人物解释，未验证完整机制。'])
